sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    describe('ATF-DT-07: Advanced Features End-to-End Validation', function() {
        var APP = 'x_2056099_indust_0.';

        it('should correctly parse natural language prompt and create customer order', function() {
            var parser = new x_2056099_indust_0.PromptIntelligentParser();
            var res = parser.processPrompt('Create order for 200 units of SKU-0010 for Honda by 2026-11-15', gs.getUserID());
            expect(res.success).toBe(true);
            expect(res.intent).toBe('CREATE_ORDER');
            expect(res.confidence >= 50).toBe(true);
            expect(res.actions.length > 0).toBe(true);
        });

        it('should correctly detect downtime intent and machine entity from prompt', function() {
            var parser = new x_2056099_indust_0.PromptIntelligentParser();
            var res = parser.processPrompt('Log downtime for machine CNC-01 urgent', gs.getUserID());
            expect(res.success).toBe(true);
            expect(res.intent).toBe('LOG_DOWNTIME');
        });

        it('should execute multi-order resequencing with priority sorting', function() {
            var scheduler = new x_2056099_indust_0.ProductionScheduler();
            expect(typeof scheduler.scheduleMultipleOrders).toBe('function');

            // Find at least 1 production order to test
            var poGr = new GlideRecord('x_2056099_indust_0_production_order');
            poGr.setLimit(2);
            poGr.query();
            var ids = [];
            while (poGr.next()) {
                ids.push(poGr.getUniqueValue());
            }

            if (ids.length > 0) {
                var multiRes = scheduler.scheduleMultipleOrders(ids);
                expect(multiRes.total_orders).toBe(ids.length);
                expect(multiRes.resequenced_results.length).toBe(ids.length);
            } else {
                expect(true).toBe(true);
            }
        });

        it('should ingest IoT telemetry and generate alert upon critical temperature threshold breach', function() {
            var gateway = new x_2056099_indust_0.IoTStreamingGateway();
            var ingestRes = gateway.ingest({
                device_id: 'CNC',
                temperature: 92.5, // Above critical threshold 85°C
                vibration: 3.2,
                power_consumption: 75.0
            });

            expect(ingestRes.success).toBe(true);
            expect(ingestRes.machine_condition).toBe('critical');
            expect(ingestRes.alerts_generated >= 0).toBe(true);
        });

        it('should calibrate resource efficiency percentage with EMA feedback', function() {
            var calEngine = new x_2056099_indust_0.ScheduleCalibrationEngine();
            expect(typeof calEngine.calibrate).toBe('function');
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
